// spec: .qa/e2e/specs/splash.md · тикет #6121eb (מסך פתיחה / Splash) — веб, гость, холодная загрузка (новое окно без кэша).
// Прелоадер — #preloader в index.html: показывается сразу, растворяется (класс done) не раньше 2.6 с, затем удаляется.
// Записываем по MutationObserver моменты смены состояния и текст #root в этот момент — так видно, что Welcome
// уже нарисован целиком к началу растворения (нет пустого тёмного экрана, реджекты 03.11 / 05.11).
import { test, expect } from '@playwright/test';

type Ev = { st: string; t: number; root: string };

const WELCOME = ['מישהו מיוחד', 'בוא/י נתחיל', 'התחברות'];

test.describe('מסך פתיחה (Splash) — веб', () => {
  test.describe.configure({ timeout: 60_000 });

  test.beforeEach(async ({ page }) => {
    await page.addInitScript(() => {
      const w = window as unknown as { __qaPre: { st: string; t: number; root: string }[] };
      w.__qaPre = [];
      const snap = () => {
        const el = document.getElementById('preloader');
        const st = el ? el.className || 'shown' : w.__qaPre.length ? 'removed' : 'absent';
        const last = w.__qaPre[w.__qaPre.length - 1];
        if (!last || last.st !== st) w.__qaPre.push({ st, t: performance.now(), root: document.getElementById('root')?.innerText ?? '' });
      };
      new MutationObserver(snap).observe(document, { subtree: true, childList: true, attributes: true, attributeFilter: ['class'] });
    });
  });

  test('холодная загрузка: прелоадер сразу, растворяется не раньше 2.6 с и только когда Welcome нарисован целиком @iphone @prod-safe (#6121eb)', async ({ page }) => {
    await page.goto('/');
    await page.waitForURL(/\/welcome/);
    await expect.poll(() => page.evaluate(() => (window as unknown as { __qaPre: Ev[] }).__qaPre.some((e) => e.st === 'removed')), { message: 'прелоадер убран', timeout: 20_000 }).toBe(true);
    const ev: Ev[] = await page.evaluate(() => (window as unknown as { __qaPre: Ev[] }).__qaPre);
    test.info().annotations.push({ type: 'preloader', description: JSON.stringify(ev.map((e) => ({ st: e.st, t: Math.round(e.t), root: e.root.slice(0, 40) }))) });

    const shown = ev.find((e) => e.st === 'shown');
    const done = ev.find((e) => e.st === 'done');
    expect(shown, 'прелоадер показан при загрузке (нет белого экрана, реджект 28.10)').toBeTruthy();
    expect(done, 'прелоадер растворяется (класс done)').toBeTruthy();
    // Анимация 2.6 с (Figma 864-315/864-676): растворение не раньше конца анимации (реджект 03.11).
    expect(done!.t - shown!.t, 'растворение не раньше 2.6 с после показа').toBeGreaterThanOrEqual(2600 - 50);
    // К моменту растворения Welcome уже нарисован целиком (реджект 05.11: нет пустого экрана, не по частям).
    for (const txt of WELCOME) expect(done!.root, `Welcome уже содержит «${txt}» в момент растворения`).toContain(txt);

    // Финал: прелоадера нет, Welcome виден.
    await expect(page.locator('#preloader')).toHaveCount(0);
    for (const txt of WELCOME) await expect(page.getByText(txt).first()).toBeVisible();
  });

  test('Welcome: «התחברות» → способы входа → «כניסה עם מספר טלפון» ведёт на /phone (вход существующего пользователя) @iphone @prod-safe (#6121eb)', async ({ page }) => {
    await page.goto('/');
    await page.waitForURL(/\/welcome/);
    await expect(page.locator('#preloader')).toHaveCount(0, { timeout: 15_000 });
    await expect(page.getByText('מישהו מיוחד')).toBeVisible(); // AC 1: экран с логотипом/заголовком Magnet
    await page.getByRole('button', { name: /התחברות/ }).click();
    // На вебе 12.11 «התחברות» сначала показывает способы входа (на том же /welcome), телефон — один из них.
    const byPhone = page.getByRole('button', { name: /כניסה עם מספר טלפון/ });
    await expect(byPhone).toBeVisible();
    await byPhone.click();
    await page.waitForURL(/\/phone/); // AC 2–3
  });

  test('Welcome: «בוא/י נתחיל» открывает лист условий (создание аккаунта начинается с согласия) @iphone @prod-safe (#6121eb)', async ({ page }) => {
    await page.goto('/');
    await page.waitForURL(/\/welcome/);
    await expect(page.locator('#preloader')).toHaveCount(0, { timeout: 15_000 });
    await page.getByRole('button', { name: 'בוא/י נתחיל' }).click();
    await page.waitForURL(/\/terms/); // AC 4–5: путь создания аккаунта → лист условий → /phone
    await expect(page.getByText('תנאי שימוש ומדיניות פרטיות').first()).toBeVisible();
    await expect(page.getByRole('button', { name: 'מסכים/ה, ממשיכים' })).toBeVisible();
    // Согласие не даём (без прокрутки и галочек кнопка недоступна) — дальше путь в /phone покрыт тестами auth-phone-otp.
    await expect(page.getByRole('button', { name: 'מסכים/ה, ממשיכים' })).toHaveAttribute('aria-disabled', 'true');
  });
});
